const researchSources = [
  {category:'공시·IR',name:'SEC EDGAR',title:'기업이 직접 제출한 공시 찾기',url:'https://www.sec.gov/edgar/search/',when:'기업의 사업과 재무 숫자를 원문에서 확인할 때',steps:['기업명이나 티커를 입력합니다. 같은 이름의 다른 법인이 아닌지 확인합니다.','문서 유형을 10-K로 좁혀 연간 자료를 찾고, 필요한 기간을 고릅니다.','제출일과 보고 대상 회계기간을 구분해 적습니다. 필요한 표와 주석의 위치를 남깁니다.'],question:'내가 인용한 숫자의 단위와 기간, 원문 위치는 무엇인가?',caution:'SEC에 제출됐다는 사실이 숫자의 정확성이나 투자 성과를 보증하지는 않습니다. 원문과 정정 문서도 확인하세요.',level:'기초 → 중급'},
  {category:'공시·IR',name:'Investor.gov',title:'10-K / 10-Q 읽는 법',url:'https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/how-read',when:'긴 보고서를 어디부터 읽을지 막막할 때',steps:['10-K의 Item 1 Business에서 사업을 이해합니다.','Item 1A Risk Factors와 Item 7 MD&A에서 위험과 경영진의 실적 설명을 읽습니다.','Item 8 재무제표와 주석으로 설명을 확인합니다. 10-Q는 구성이 다르므로 항목 번호 대신 제목을 찾습니다.'],question:'사업 설명, 위험, 숫자가 서로 일치하는가?',caution:'미국 외 기업은 다른 양식을 사용할 수 있습니다. 미국 상장이라는 이유만으로 모두 같은 공시 체계라고 가정하지 마세요.',level:'기초'},
  {category:'공시·IR',name:'Microsoft Investor Relations',title:'실적 자료를 한 묶음으로 읽는 연습',url:'https://www.microsoft.com/en-us/investor/default',when:'실제 기업의 실적 발표 자료로 연습하고 싶을 때',steps:['IR에서 Earnings 또는 Annual Reports 메뉴를 찾습니다.','같은 분기의 실적 보도자료와 발표 자료, 제공되는 웹캐스트·스크립트를 함께 엽니다.','회사가 제시한 실적과 전망을 구분하고, 사업부별 수치의 기간과 정의를 확인합니다.'],question:'성장한 사업부는 어디이며, 성장 원인은 수요·가격·환율 중 무엇인가?',caution:'공식 IR도 경영진 관점의 설명입니다. 공시의 위험과 주석, 경쟁사 자료를 함께 읽으세요. 기업 예시는 매수 추천이 아닙니다.',level:'실전 연습'},
  {category:'공시·IR',name:'NVIDIA Investor Relations',title:'연차보고서와 위임장 자료 찾기',url:'https://investor.nvidia.com/financial-info/annual-reports-and-proxies/default.aspx',when:'사업뿐 아니라 경영진과 주주 관련 정보도 볼 때',steps:['공식 Annual Reports and Proxies 페이지에서 연도를 고릅니다.','연차보고서의 사업 구성과 위험을 읽고, 전년 문서와 달라진 표현을 찾습니다.','Proxy 자료에서 경영진 보상과 지배구조 관련 항목을 찾아 질문을 기록합니다.'],question:'경영진의 보상 기준은 내가 중요하게 보는 장기 성과와 연결되는가?',caution:'회사별 지표 정의가 다릅니다. 특정 기업의 수치를 다른 산업에 그대로 적용하지 마세요.',level:'중급'},
  {category:'강의·블로그',name:'NYU Stern · Aswath Damodaran',title:'가치평가 공개 영상 강의',url:'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/webcastvalonline.htm',when:'성장 전망을 기업가치 가정으로 바꾸는 법을 배울 때',steps:['공식 강의 페이지에서 첫 영상부터 시청합니다. YouTube 영상과 강의 자료가 연결되어 있습니다.','영상 한 편을 본 뒤 개념 하나와 모르는 용어 하나만 적습니다.','예제의 성장률이나 할인율을 바꿔 결론이 얼마나 변하는지 생각합니다.'],question:'이 가치평가에서 결론을 가장 크게 바꾸는 가정은 무엇인가?',caution:'영어 강의입니다. 자막·번역을 활용하되 숫자와 전문 용어는 원문으로 확인하세요. 과거 예제는 현재 적정가가 아닙니다.',level:'중급'},
  {category:'강의·블로그',name:'Musings on Markets',title:'기업 이야기와 숫자를 연결하는 글',url:'https://aswathdamodaran.blogspot.com/2014/06/numbers-and-narrative-modeling-story.html',when:'“좋은 기업 같다”는 생각을 분석으로 발전시킬 때',steps:['작성일을 확인하고 글의 기업 이야기와 숫자 가정을 나눠 읽습니다.','동의하는 주장 하나와 반박할 수 있는 주장 하나를 적습니다.','내 관심 기업에 적용할 때는 해당 기업의 최신 공시로 가정을 다시 검증합니다.'],question:'내가 믿는 이야기를 검증할 숫자는 무엇인가?',caution:'2014년의 교육용 글입니다. 현재 기업 전망이나 매매 신호로 사용하지 마세요.',level:'중급'},
  {category:'강의·블로그',name:'Berkshire Hathaway',title:'주주서한으로 사고방식 배우기',url:'https://www.berkshirehathaway.com/letters/letters.html',when:'장기 관점의 사업 평가와 자본 배분을 공부할 때',steps:['연도별 원문 중 하나를 골라 작성자와 당시 상황을 확인합니다.','인수·재투자·자사주 매입 등 자금 사용에 관한 설명을 찾아 읽습니다.','투자 원칙과 특정 시점의 판단을 구분해 나만의 문장으로 정리합니다.'],question:'경영진은 번 돈을 어디에 쓰며, 그 이유를 어떻게 설명하는가?',caution:'다른 기업의 자본 구조와 투자 기회는 다릅니다. 유명 투자자의 과거 결정을 그대로 따라 하지 마세요.',level:'기초 → 중급'},
  {category:'산업·매크로',name:'FRED · St. Louis Fed',title:'뉴스 속 경제지표를 원자료로 확인하기',url:'https://fred.stlouisfed.org/',when:'금리·물가·고용 뉴스의 장기 흐름을 비교할 때',steps:['관심 지표를 검색하고 출처·단위·주기부터 확인합니다.','차트 기간을 넓혀 최근 움직임과 과거 흐름을 비교합니다.','지수 수준인지 변화율인지 확인하고 관측일과 업데이트 시점을 노트에 적습니다.'],question:'이 지표의 변화는 기업의 매출·원가·차입비용 중 어디로 전달되는가?',caution:'지표마다 발표 시차와 수정 여부가 다릅니다. 두 그래프가 함께 움직여도 인과관계가 확인된 것은 아닙니다.',level:'기초 → 중급'},
  {category:'해석 검증',name:'SEC · Analyzing Analyst Recommendations',title:'애널리스트 의견을 읽는 기준',url:'https://www.sec.gov/about/reports-publications/investorpubsanalystshtm',when:'목표주가나 투자 의견을 참고할 때',steps:['등급보다 분석의 논리와 가정, 작성일을 먼저 봅니다.','실적 추정, 가치평가 방식, 위험 요인을 나눠 기록합니다.','작성자의 이해관계와 공개된 유의사항을 확인하고 공시 원문과 대조합니다.'],question:'목표주가가 아니라 그 가격을 만든 가정에 동의하는가?',caution:'오래된 투자자 교육 자료입니다. 분석가 이해관계를 이해하는 데 활용하고, 당시 규정 설명을 최신 규정으로 간주하지 마세요.',level:'기초'}
];
const researchTips=[
 ['검색어를 바꾸면 자료가 달라집니다','“기업명 주가 전망”만 검색하기보다 “기업명 investor relations”, “기업명 annual report”, “기업명 earnings release”를 사용하세요. 검색 결과에서 회사 공식 도메인을 확인한 뒤 들어갑니다.'],
 ['보고서 전체를 처음부터 번역하지 마세요','먼저 목차를 보고 궁금한 항목만 읽습니다. 페이지 내 찾기로 revenue(매출), segment(사업부), cash flow(현금흐름), debt(부채)를 찾아보세요. 표의 제목과 주석까지 함께 확인합니다.'],
 ['숫자는 다섯 가지 꼬리표와 함께 기록하세요','값 + 단위 + 대상 기간 + 회계 기준 + 원문 링크. 예를 들어 분기 매출과 연간 매출, 실제 EPS와 예상 EPS, GAAP와 조정 이익을 섞지 않습니다. FY는 회계연도이며 달력연도와 다를 수 있습니다.'],
 ['실적 발표는 준비된 발표와 Q&A를 나눠 읽으세요','발표문에서 회사의 핵심 주장을 파악한 뒤 질의응답에서 반복된 질문과 답하지 않은 부분을 적습니다. 모호한 답변만으로 문제라고 단정하지 말고 다음 분기의 확인 항목으로 남깁니다.'],
 ['경쟁사 한 곳을 같은 기준으로 비교하세요','같은 고객을 두고 경쟁하는 회사의 IR도 읽습니다. 보고 기간·지표 정의·사업 구성 차이를 맞춘 뒤 성장과 이익률을 비교하세요. 기업 전체보다 겹치는 사업부의 비교가 더 유용할 수 있습니다.'],
 ['유튜브 한 편마다 “주장–근거–반론” 세 줄','영상에서 주장 하나를 고르고, 근거가 나온 원문과 날짜를 찾고, 반대 설명을 적습니다. 원문 링크·수치의 기간·가정·이해관계 공개가 있는지 보세요. 조회 수와 확신에 찬 말투는 검증을 대신하지 못합니다.'],
 ['블로그 여러 개도 출처가 하나일 수 있습니다','여러 글이 같은 기사나 보고서를 다시 인용했다면 독립적인 증거가 늘어난 것은 아닙니다. 인용 경로를 거슬러 올라가 최초 자료를 확인하세요. 잘린 차트는 전체 기간과 축을 확인합니다.'],
 ['무료 자료부터 충분히 활용하세요','공시와 공식 IR로 기본 분석을 먼저 완성합니다. 유료 자료가 필요하다면 내가 채우려는 정보의 빈칸이 무엇인지 정한 뒤 판단하세요. 비싼 구독료가 분석의 정확도를 보증하지 않습니다.'],
 ['AI 요약은 원문을 찾는 보조 도구로','공시를 요약시킬 때 문서명·대상 기간·표나 항목 위치를 함께 요청하세요. 없는 수치가 섞이거나 단위가 바뀔 수 있으므로 원문에서 대조합니다. 자료에 없는 전망은 사실과 분리하세요.'],
 ['공부를 끝내는 기준을 정하세요','뉴스를 다 읽는 대신 사업모델 3문장, 핵심 지표 3개, 위험 2개, 다음 질문 1개를 완성하세요. 첫 분석은 결론을 확정하는 시간이 아니라 더 확인할 질문을 만드는 시간입니다.']
];
function research(){
 const selected=researchSources.filter(s=>filter==='전체'||s.category===filter);
 return head('기업 분석, 어디서부터 볼까요?','찾는 곳 → 읽는 방법 → 기록할 질문. 원문을 읽는 습관부터 만들어 보세요.')+
 `<section class="panel research-start"><div><span class="tag">START WITH ONE COMPANY</span><h2>첫 기업 분석은 60분만 시작해 보세요</h2><p class="note">앱이 제안하는 입문 루틴입니다. 60분 만에 투자 결론을 내리기 위한 절차는 아닙니다.</p></div><button class="primary" data-go="notebook">기업 분석 노트 열기 →</button></section>
 <div class="study-flow">${[['10분','공식 IR 찾기','사업과 주요 제품을 세 문장으로 정리'],['20분','공시 읽기','매출·이익·현금흐름과 기간을 기록'],['15분','실적 설명 듣기','변화 원인과 전망을 구분'],['15분','경쟁사·반론 확인','위험 두 개와 다음 질문 하나']].map(([time,title,desc],i)=>`<article><span class="tag">0${i+1} · ${time}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div>
 <div class="section-title"><h2>목적별 자료 찾기</h2><span class="note">원문 링크 확인 · 2026.09.21</span></div><p class="note">공식 자료는 사실을 확인하는 출발점, 강의와 분석 글은 질문을 만드는 보조 자료입니다. 아래 읽는 순서와 질문은 앱의 학습 가이드입니다. 링크의 영어 원문은 외부 사이트에서 열립니다.</p>
 <div class="topic-chips">${['전체','공시·IR','강의·블로그','산업·매크로','해석 검증'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div>
 <div class="resource-grid">${selected.map(s=>`<article class="panel resource"><span class="tag">${s.category} · ${s.level}</span><h3>${s.title}</h3><p>${s.when}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ↗</a><details class="research-detail"><summary>무엇을 보고 어떻게 공부할까?</summary><ol>${s.steps.map(t=>`<li>${t}</li>`).join('')}</ol><div class="research-question"><strong>노트에 남길 질문</strong><br>${s.question}</div><p class="note" style="margin-top:12px">${s.caution}</p></details></article>`).join('')}</div>
 <div class="section-title"><h2>보고서를 펼쳤다면, 이 순서로</h2></div><section class="panel"><p class="note">미국 기업의 10-K를 처음 읽을 때의 출발점입니다. 아래 항목의 역할은 <a href="https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/how-read" target="_blank" rel="noopener noreferrer">Investor.gov 설명</a>에서 확인할 수 있습니다.</p><div class="report-map">${[['Item 1 · Business','무엇으로 돈을 버는가?','고객·제품·지역·경쟁자를 연결해 보기'],['Item 1A · Risk Factors','어떤 일이 사업을 흔들 수 있는가?','일반적인 위험과 회사 고유 위험 구분하기'],['Item 7 · MD&A','왜 실적이 바뀌었는가?','가격·판매량·원가 변화에 대한 설명 찾기'],['Item 8 · Financial Statements','설명과 숫자가 맞는가?','재무제표와 주석을 함께 읽기']].map(([t,q,d])=>`<div><span class="tag">${t}</span><h3>${q}</h3><p class="note">${d}</p></div>`).join('')}</div><p class="note">10-K는 연간, 10-Q는 분기 자료입니다. 미국 외 기업의 공시는 양식이 다를 수 있습니다. 문서의 이름·대상 기간·목차를 먼저 확인하세요.</p></section>
 <div class="section-title"><h2>공부 시간을 아껴주는 10가지 팁</h2></div><section class="panel">${researchTips.map(([t,d],i)=>`<details class="research-detail"><summary><span class="tip-number">${String(i+1).padStart(2,'0')}</span>${t}</summary><p>${d}</p></details>`).join('')}</section>
 <div class="section-title"><h2>매주 반복할 작은 루틴</h2></div><section class="panel"><div class="two-col"><div><h3>평소에는 주 30분</h3><p class="note">공식 발표 한 개 읽기 10분 → 관심 기업과의 연결 정리 10분 → 분석 노트의 확인 질문 업데이트 10분.</p></div><div><h3>실적 발표 때는 비교 중심</h3><p class="note">이전 분기 노트를 먼저 읽고 실제 결과와 예상의 차이를 표시하세요. 수치의 개선·악화 이유를 적고 다음 분기 확인 항목 하나를 남깁니다.</p></div></div><button class="secondary" data-go="notebook">내 기업에 적용하기 →</button></section>`;
}
